PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS kingdoms(id INTEGER PRIMARY KEY, name TEXT NOT NULL);
INSERT OR IGNORE INTO kingdoms VALUES(1,'Aurora'),(2,'Véu do Norte');
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, login TEXT NOT NULL UNIQUE COLLATE NOCASE, password TEXT NOT NULL, salt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS governors(id TEXT PRIMARY KEY REFERENCES users(id), name TEXT NOT NULL UNIQUE COLLATE NOCASE, kingdom INTEGER NOT NULL REFERENCES kingdoms(id), civilization TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS cities(owner TEXT PRIMARY KEY REFERENCES governors(id), kingdom INTEGER NOT NULL REFERENCES kingdoms(id), x INTEGER NOT NULL, y INTEGER NOT NULL, last_production INTEGER NOT NULL, UNIQUE(kingdom,x,y));
CREATE TABLE IF NOT EXISTS balances(owner TEXT NOT NULL REFERENCES governors(id), resource TEXT NOT NULL, amount INTEGER NOT NULL CHECK(amount>=0 AND amount<=10000), PRIMARY KEY(owner,resource));
CREATE TABLE IF NOT EXISTS ledger(id INTEGER PRIMARY KEY AUTOINCREMENT, owner TEXT NOT NULL REFERENCES governors(id), resource TEXT NOT NULL, delta INTEGER NOT NULL, reason TEXT NOT NULL, command TEXT, at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS buildings(owner TEXT NOT NULL REFERENCES governors(id), kind TEXT NOT NULL, level INTEGER NOT NULL CHECK(level BETWEEN 0 AND 5), PRIMARY KEY(owner,kind));
CREATE TABLE IF NOT EXISTS queues(id TEXT PRIMARY KEY, owner TEXT NOT NULL REFERENCES governors(id), kind TEXT NOT NULL, target INTEGER NOT NULL, starts INTEGER NOT NULL, ends INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','done')), rules_version INTEGER NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_queue ON queues(owner) WHERE status='active';
CREATE TABLE IF NOT EXISTS alliances(id TEXT PRIMARY KEY, kingdom INTEGER NOT NULL REFERENCES kingdoms(id), name TEXT NOT NULL COLLATE NOCASE, tag TEXT NOT NULL COLLATE NOCASE, UNIQUE(kingdom,name), UNIQUE(kingdom,tag));
CREATE TABLE IF NOT EXISTS members(owner TEXT PRIMARY KEY REFERENCES governors(id), alliance TEXT NOT NULL REFERENCES alliances(id), rank INTEGER NOT NULL CHECK(rank BETWEEN 1 AND 5));
CREATE TABLE IF NOT EXISTS applications(owner TEXT NOT NULL REFERENCES governors(id), alliance TEXT NOT NULL REFERENCES alliances(id), PRIMARY KEY(owner,alliance));
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY AUTOINCREMENT, channel TEXT NOT NULL, author TEXT NOT NULL REFERENCES governors(id), body TEXT NOT NULL, at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS messages_page ON messages(channel,id);
CREATE TABLE IF NOT EXISTS commands(owner TEXT NOT NULL REFERENCES governors(id), key TEXT NOT NULL, fingerprint TEXT NOT NULL, result TEXT NOT NULL, PRIMARY KEY(owner,key));
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY AUTOINCREMENT, actor TEXT NOT NULL, action TEXT NOT NULL, payload TEXT NOT NULL, at INTEGER NOT NULL);
INSERT OR IGNORE INTO schema_migrations VALUES(1);
